
from unittest.mock import Mock, patch

from fastapi.testclient import TestClient

from app.main import app


client = TestClient(app)


def test_analytics_ask_success():

    provider = Mock()

    # =========================================
    # FIRST SQL GENERATED BY THE LLM
    # =========================================
    #
    # The SQL is syntactically valid but
    # semantically invalid for our database.
    #
    # "price" does not exist in products.
    #
    # This intentionally triggers the
    # self-correction mechanism.

    provider.generate_sql.return_value = """
        SELECT
            name,
            price
        FROM products
        LIMIT 5
    """

    # =========================================
    # CORRECTED SQL
    # =========================================

    provider.correct_sql.return_value = """
        SELECT
            name,
            selling_price
        FROM products
        LIMIT 5
    """

    # =========================================
    # AI CHART PLAN
    # =========================================

    provider.generate_chart_plan.return_value = """
    {
        "chart_type": "bar",
        "x_axis": "name",
        "y_axis": "selling_price",
        "title": "Product Selling Prices",
        "reason": "Compare selling prices between products."
    }
    """

    # =========================================
    # AI BUSINESS ANALYSIS
    # =========================================

    provider.generate_analysis.return_value = """
    {
        "summary": "The query returned five products and their selling prices.",
        "insights": [
            "Five products were returned.",
            "The query contains product selling prices."
        ]
    }
    """

    # =========================================
    # MOCK LLM
    # =========================================

    with patch(
        "app.services.ai_service.get_llm_provider",
        return_value=provider,
    ), patch(
        "app.services.analysis_service.get_llm_provider",
        return_value=provider,
    ), patch(
        "app.services.chart_service.get_llm_provider",
        return_value=provider,
    ):

        response = client.post(
            "/analytics/ask",
            json={
                "question": (
                    "Quais são alguns produtos "
                    "e seus preços de venda?"
                )
            },
        )

    # =========================================
    # HTTP RESPONSE
    # =========================================

    assert response.status_code == 200

    data = response.json()

    # =========================================
    # QUESTION
    # =========================================

    assert data["question"] == (
        "Quais são alguns produtos "
        "e seus preços de venda?"
    )

    # =========================================
    # FINAL SQL
    # =========================================

    assert "selling_price" in data["sql"]

    # The corrected SQL must use selling_price.
    # The standalone invalid column "price" must not
    # appear in the SELECT expression.

    select_part = data["sql"].lower().split("from", 1)[0]

    assert " price" not in select_part

    # =========================================
    # DATA
    # =========================================

    assert "data" in data

    assert data["data"]["columns"]

    assert data["data"]["rows"]

    assert data["data"]["row_count"] > 0

    assert "name" in data["data"]["columns"]

    assert "selling_price" in data["data"]["columns"]

    # =========================================
    # SELF-CORRECTION
    # =========================================

    assert data["metadata"]["attempts"] == 2

    assert data["metadata"]["corrections"] == 1

    # Backward compatibility with the
    # top-level metadata fields.

    assert data["attempts"] == 2

    assert data["corrections"] == 1

    # =========================================
    # ANALYSIS
    # =========================================

    assert "analysis" in data

    assert data["analysis"]["summary"]

    assert isinstance(
        data["analysis"]["insights"],
        list,
    )

    assert len(
        data["analysis"]["insights"]
    ) > 0

    # =========================================
    # VISUALIZATION
    # =========================================

    assert "visualization" in data

    if data["visualization"] is not None:

        assert "plan" in data["visualization"]

        assert "chart" in data["visualization"]


def test_analytics_ask_empty_question():

    response = client.post(
        "/analytics/ask",
        json={
            "question": ""
        },
    )

    assert response.status_code == 422

